const t0=Date.now(); const xp0=sdk.getSkillXp('Thieving'); let n=0, minHp=99;
while (Date.now()-t0 < 20000) {
  const s = sdk.getState();
  if (s.dialog?.isOpen) { await sdk.sendClickDialog(0); continue; }
  const hp = s.player.hp; minHp=Math.min(minHp,hp);
  if (hp <= 5) { await sdk.waitForTicks(10); continue; }
  const g = s.nearbyNpcs.filter(x=>/^guard$/i.test(x.name) && !x.unreachable).sort((a,b)=>a.distance-b.distance)[0];
  if (!g) { await sdk.waitForTicks(2); continue; }
  const opt = g.optionsWithIndex.find(o=>/pickpocket/i.test(o.text));
  await sdk.sendInteractNpc(g.index, opt.opIndex); n++;
  await new Promise(r=>setTimeout(r,100));
}
return {n, xpGain: sdk.getSkillXp('Thieving')-xp0, minHp, hp: sdk.getState().player.hp, lvl: sdk.getSkill('Thieving').level, msgs: sdk.getState().gameMessages.slice(-6).map(m=>m.text)};

